162	          <p style="color:#6b7280;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
163	      `),
164	      text: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
165	      ...buildReplyTo(options),
166	    });
167	    return true;
168	  } catch (error) {
169	    console.error("[email] Failed to send merchant waitlist alert:", error);
170	    return false;
171	  }
172	}
173	
