1	import { useState, useCallback, useEffect } from "react";
2	import type {
3	  ActionFunctionArgs,
4	  HeadersFunction,
5	  LoaderFunctionArgs,
6	} from "react-router";
7	import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
8	import { useAppBridge } from "@shopify/app-bridge-react";
9	import { authenticate } from "../shopify.server";
10	import { boundary } from "@shopify/shopify-app-react-router/server";
11	import { getShopSubscription } from "../billing.server";
12	import { PLAN_LIMITS, UNLIMITED } from "../plans";
13	import db from "../db.server";
14	import { sendTestEmail } from "../email.server";
15	import {
16	  Page,
17	  Layout,
18	  Card,
19	  BlockStack,
20	  InlineStack,
21	  Text,
22	  Badge,
23	  Button,
24	  Divider,
25	  Box,
26	  Select,
27	  TextField,
28	  Banner,
29	  Icon,
30	  ProgressBar,
31	} from "@shopify/polaris";
32	import {
33	  LocationIcon,
34	  DeliveryIcon,
35	  PersonIcon,
36	  DisabledIcon,
37	} from "@shopify/polaris-icons";
38	
39	// ---------------------------------------------------------------------------
40	// Loader
41	// ---------------------------------------------------------------------------
42	
43	export const loader = async ({ request }: LoaderFunctionArgs) => {
44	  const { session, admin } = await authenticate.admin(request);
45	  const shop = session.shop;
46	
47	  const [subscription, zipCount, deliveryRuleCount, waitlistCount, blockedZipCount, shopSettings, shopResponse] = await Promise.all([
48	    getShopSubscription(shop),
49	    db.zipCode.count({ where: { shop } }),
50	    db.deliveryRule.count({ where: { shop } }),
51	    db.waitlistEntry.count({ where: { shop } }),
52	    db.zipCode.count({ where: { shop, type: "blocked" } }),
53	    db.shopSettings.findUnique({ where: { shop } }),
54	    admin.graphql(`{ shop { name } }`),
55	  ]);
56	
57	  const shopData = await shopResponse.json();
58	  const shopName: string = shopData.data?.shop?.name ?? shop.replace(".myshopify.com", "");
59	
60	  // Cache the shop display name so email service can use it without API calls
61	  await db.shopSettings.upsert({
62	    where: { shop },
63	    create: { shop, shopName },
64	    update: { shopName },
65	  });
66	
67	  return {
68	    subscription,
69	    zipCount,
70	    deliveryRuleCount,
71	    waitlistCount,
72	    blockedZipCount,
73	    shop,
74	    shopName,
75	    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
76	    notificationEmail: shopSettings?.notificationEmail ?? "",
77	    emailSenderName: shopSettings?.emailSenderName ?? "",
78	    emailReplyTo: shopSettings?.emailReplyTo ?? "",
79	  };
80	};
81	
82	// ---------------------------------------------------------------------------
83	// Action
84	// ---------------------------------------------------------------------------
85	
86	export const action = async ({ request }: ActionFunctionArgs) => {
87	  const { session } = await authenticate.admin(request);
88	  const shop = session.shop;
89	
90	  const formData = await request.formData();
91	  const intent = formData.get("intent") as string;
92	
93	  try {
94	    if (intent === "save-behavior") {
95	      const defaultBehavior = formData.get("defaultBehavior") as string;
96	      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
97	        return { error: "Invalid value for defaultBehavior" };
98	      }
99	      await db.shopSettings.upsert({
100	        where: { shop },
101	        create: { shop, defaultBehavior },
102	        update: { defaultBehavior },
103	      });
104	      return { success: true, intent };
105	    }
106	
107	    if (intent === "save-notification") {
108	      const notificationEmail =
109	        (formData.get("notificationEmail") as string | null) ?? "";
110	      await db.shopSettings.upsert({
111	        where: { shop },
112	        create: { shop, notificationEmail: notificationEmail || null },
113	        update: { notificationEmail: notificationEmail || null },
114	      });
115	      return { success: true, intent };
116	    }
117	
118	    if (intent === "save-email-settings") {
119	      const emailSenderName =
120	        (formData.get("emailSenderName") as string | null)?.trim() || null;
121	      const emailReplyTo =
122	        (formData.get("emailReplyTo") as string | null)?.trim() || null;
123	      await db.shopSettings.upsert({
124	        where: { shop },
125	        create: { shop, emailSenderName, emailReplyTo },
126	        update: { emailSenderName, emailReplyTo },
127	      });
128	      return { success: true, intent };
129	    }
130	
131	    if (intent === "send-test-email") {
132	      const testEmail = (formData.get("testEmail") as string | null) ?? "";
133	      if (!testEmail) return { error: "No email address provided." };
134	      const settings = await db.shopSettings.findUnique({ where: { shop } });
135	      const sent = await sendTestEmail(
136	        testEmail,
137	        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
138	        shop,
139	      );
140	      return sent
141	        ? { success: true, intent }
142	        : { error: "Failed to send test email. Check your Resend API key and sender email." };
143	    }
144	
145	    return { error: "Unknown intent" };
146	  } catch {
147	    return { error: "Failed to save settings. Please try again." };
148	  }
149	};
150	
151	// ---------------------------------------------------------------------------
152	// Component
153	// ---------------------------------------------------------------------------
154	
155	export default function SettingsPage() {
156	  const { subscription, zipCount, deliveryRuleCount, waitlistCount, blockedZipCount, shopName, defaultBehavior, notificationEmail, emailSenderName, emailReplyTo } =
157	    useLoaderData<typeof loader>();
158	  const navigate = useNavigate();
159	  const shopify = useAppBridge();
160	  const limits = PLAN_LIMITS[subscription.planTier];
161	
162	  // Fetchers — one per save section so loading states stay independent
163	  const behaviorFetcher = useFetcher<typeof action>();
164	  const notificationFetcher = useFetcher<typeof action>();
165	  const emailSettingsFetcher = useFetcher<typeof action>();
166	  const testEmailFetcher = useFetcher<typeof action>();
167	
168	  // Local controlled state
169	  const [behaviorValue, setBehaviorValue] = useState(defaultBehavior);
170	  const [emailValue, setEmailValue] = useState(notificationEmail);
171	  const [senderNameValue, setSenderNameValue] = useState(emailSenderName);
172	  const [replyToValue, setReplyToValue] = useState(emailReplyTo);
173	
174	  const isSavingBehavior = behaviorFetcher.state !== "idle";
175	  const isSavingNotification = notificationFetcher.state !== "idle";
176	  const isSavingEmailSettings = emailSettingsFetcher.state !== "idle";
177	  const isSaving = isSavingBehavior || isSavingNotification || isSavingEmailSettings;
178	
179	  // Track dirty state
180	  const isDirty =
181	    behaviorValue !== defaultBehavior ||
182	    emailValue !== notificationEmail ||
183	    senderNameValue !== emailSenderName ||
184	    replyToValue !== emailReplyTo;
185	
186	  // Toast on success
187	  useEffect(() => {
188	    if (
189	      behaviorFetcher.data &&
190	      "success" in behaviorFetcher.data &&
191	      behaviorFetcher.data.success
192	    ) {
193	      shopify.toast.show("Settings saved");
194	    }
195	  }, [behaviorFetcher.data, shopify]);
196	
197	  useEffect(() => {
198	    if (
199	      notificationFetcher.data &&
200	      "success" in notificationFetcher.data &&
201	      notificationFetcher.data.success
202	    ) {
203	      shopify.toast.show("Settings saved");
204	    }
205	  }, [notificationFetcher.data, shopify]);
206	
207	  useEffect(() => {
208	    if (
209	      emailSettingsFetcher.data &&
210	      "success" in emailSettingsFetcher.data &&
211	      emailSettingsFetcher.data.success
212	    ) {
213	      shopify.toast.show("Email settings saved");
214	    }
215	  }, [emailSettingsFetcher.data, shopify]);
216	
217	  useEffect(() => {
218	    if (
219	      testEmailFetcher.data &&
220	      "success" in testEmailFetcher.data &&
221	      testEmailFetcher.data.success
222	    ) {
223	      shopify.toast.show("Test email sent!");
224	    }
225	  }, [testEmailFetcher.data, shopify]);
226	
227	  const handleBehaviorChange = useCallback(
228	    (value: string) => setBehaviorValue(value),
229	    [],
230	  );
231	
232	  const handleEmailChange = useCallback(
233	    (value: string) => setEmailValue(value),
234	    [],
235	  );
236	
237	  const handleSaveAll = useCallback(() => {
238	    if (behaviorValue !== defaultBehavior) {
239	      const fd = new FormData();
240	      fd.append("intent", "save-behavior");
241	      fd.append("defaultBehavior", behaviorValue);
242	      behaviorFetcher.submit(fd, { method: "post" });
243	    }
244	    if (emailValue !== notificationEmail) {
245	      const fd = new FormData();
246	      fd.append("intent", "save-notification");
247	      fd.append("notificationEmail", emailValue);
248	      notificationFetcher.submit(fd, { method: "post" });
249	    }
250	    if (senderNameValue !== emailSenderName || replyToValue !== emailReplyTo) {
251	      const fd = new FormData();
252	      fd.append("intent", "save-email-settings");
253	      fd.append("emailSenderName", senderNameValue);
254	      fd.append("emailReplyTo", replyToValue);
255	      emailSettingsFetcher.submit(fd, { method: "post" });
256	    }
257	  }, [behaviorFetcher, notificationFetcher, emailSettingsFetcher, behaviorValue, emailValue, senderNameValue, replyToValue, defaultBehavior, notificationEmail, emailSenderName, emailReplyTo]);
258	
259	  const handleDiscard = useCallback(() => {
260	    setBehaviorValue(defaultBehavior);
261	    setEmailValue(notificationEmail);
262	    setSenderNameValue(emailSenderName);
263	    setReplyToValue(emailReplyTo);
264	  }, [defaultBehavior, notificationEmail, emailSenderName, emailReplyTo]);
265	
266	  const handleSendTestEmail = useCallback(() => {
267	    if (!emailValue) return;
268	    const fd = new FormData();
269	    fd.append("intent", "send-test-email");
270	    fd.append("testEmail", emailValue);
271	    testEmailFetcher.submit(fd, { method: "post" });
272	  }, [emailValue, testEmailFetcher]);
273	
274	  const behaviorOptions = [
275	    {
276	      label: "Block — show 'not available' message (recommended)",
277	      value: "block",
278	    },
279	    {
280	      label: "Allow — treat as available (for stores with broad coverage)",
281	      value: "allow",
282	    },
283	  ];
284	
285	  const planBadgeTone =
286	    subscription.planTier === "ultimate"
287	      ? ("success" as const)
288	      : subscription.planTier === "pro"
289	        ? ("info" as const)
290	        : subscription.planTier === "starter"
291	          ? ("attention" as const)
292	          : ("new" as const);
293	
294	  const planLabel = limits.label;
295	
296	  return (
297	    <Page
298	      title="Settings"
299	      subtitle="Manage your app settings and subscription"
300	      backAction={{ onAction: () => navigate("/app") }}
301	      primaryAction={isDirty ? {
302	        content: "Save",
303	        onAction: handleSaveAll,
304	        loading: isSaving,
305	      } : undefined}
306	      secondaryActions={isDirty ? [{
307	        content: "Discard",
308	        onAction: handleDiscard,
309	      }] : []}
310	    >
311	      <Box paddingBlockEnd="1600">
312	        <Layout>
313	
314	          {/* ----------------------------------------------------------------
315	              Section 1: Plan & Usage (merged)
316	          ---------------------------------------------------------------- */}
317	          <Layout.Section>
318	            <Card>
319	              <BlockStack gap="400">
320	                <InlineStack align="space-between" blockAlign="center">
321	                  <BlockStack gap="050">
322	                    <InlineStack gap="200" blockAlign="center">
323	                      <Text as="h2" variant="headingMd">
324	                        {planLabel} Plan
325	                      </Text>
326	                      <Badge tone={planBadgeTone}>Active</Badge>
327	                    </InlineStack>
328	                    <Text as="p" tone="subdued" variant="bodySm">
329	                      {subscription.planTier === "free"
330	                        ? "Limited features"
331	                        : subscription.planTier === "starter"
332	                          ? "Essential features"
333	                          : subscription.billingInterval === "annual"
334	                            ? "Billed annually"
335	                            : "Billed monthly"}
336	                    </Text>
337	                  </BlockStack>
338	                  <Button
339	                    variant="primary"
340	                    onClick={() => navigate("/app/pricing")}
341	                  >
342	                    {subscription.planTier === "free" || subscription.planTier === "starter"
343	                      ? "Upgrade"
344	                      : "Manage"}
345	                  </Button>
346	                </InlineStack>
347	                <Divider />
348	                {/* Usage */}
349	                <BlockStack gap="400">
350	                  {/* Zip Codes */}
351	                  <BlockStack gap="200">
352	                    <InlineStack align="space-between" blockAlign="center">
353	                      <InlineStack gap="200" blockAlign="center">
354	                        <Icon source={LocationIcon} tone="subdued" />
355	                        <Text as="p" variant="bodyMd">Zip Codes</Text>
356	                      </InlineStack>
357	                      {limits.maxZipCodes < UNLIMITED ? (
