51	export const loader = async ({ request }: LoaderFunctionArgs) => {
52	  const { session } = await authenticate.admin(request);
53	  const shop = session.shop;
54	
55	  const [entries, subscription] = await Promise.all([
56	    db.waitlistEntry.findMany({
57	      where: { shop },
58	      orderBy: { createdAt: "desc" },
59	    }),
60	    getShopSubscription(shop),
61	  ]);
62	
63	  const stats = {
64	    total: entries.length,
65	    waiting: entries.filter((e) => e.status === "waiting").length,
66	    accepted: entries.filter((e) => e.status === "accepted").length,
67	    rejected: entries.filter((e) => e.status === "rejected").length,
68	    notified: entries.filter((e) => e.status === "notified").length,
69	    converted: entries.filter((e) => e.status === "converted").length,
70	    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
71	  };
72	
73	  return { entries, stats, subscription };
74	};
