28	function getClient(): Resend | null {
29	  if (client) return client;
30	  const apiKey = process.env.RESEND_API_KEY;
31	  if (!apiKey) {
32	    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
33	    return null;
34	  }
35	  client = new Resend(apiKey);
36	  return client;
37	}
38	
39	/**
40	 * Returns true if the Resend API key is configured and the client can be
41	 * initialized. Callers use this to show actionable diagnostics in the UI
42	 * (e.g. "API key missing" vs "send failed") without attempting a live send.
43	 */
44	export function isEmailConfigured(): boolean {
45	  return Boolean(process.env.RESEND_API_KEY);
46	}
47	
48	function getRawFromEmail(): string {
49	  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
50	}
51	
52	function shopFallbackName(shop: string, options?: EmailOptions): string {
53	  return options?.shopDisplayName?.trim() || shop.replace(".myshopify.com", "");
54	}
55	
56	/**
57	 * Build the full From address with display name.
58	 *
59	 * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
60	 * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
61	 */
62	function buildFrom(shop: string, options?: EmailOptions): string {
63	  const displayName = options?.senderName?.trim() || shopFallbackName(shop, options);
64	  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
65	}
66	
67	/**
68	 * Build optional reply_to field. Returns undefined when not configured
69	 * so it can be spread into the Resend payload without adding an empty header.
70	 */
71	function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
72	  const replyTo = options?.replyTo?.trim();
73	  if (replyTo) return { reply_to: replyTo };
74	  return {};
